example_class.code:
classDiagram
    class Customer {
        +String customerId
        +String name
    }
    class Order {
        +String orderId
        +Date orderDate
        +String status
        +submit()
        +cancel()
    }
    class OrderItem {
        +String productId
        +int quantity
    }
    Customer "1" --> "*" Order : 下訂
    Order "1" *-- "1..*" OrderItem : 包含

example_er.code:
erDiagram
    CUSTOMER ||--o{ ORDERS : "下訂"
    ORDERS ||--|{ ORDER_ITEM : "包含"
    PRODUCT ||--o{ ORDER_ITEM : "被訂購"
    CUSTOMER {
        string customer_id PK "客戶編號"
        string name "客戶名稱"
        string email "電子郵件"
    }
    ORDERS {
        string order_id PK "訂單編號"
        string customer_id FK "客戶編號"
        date order_date "訂單日期"
        string status "訂單狀態"
    }
    ORDER_ITEM {
        string order_id FK "訂單編號"
        string product_id FK "商品編號"
        int quantity "數量"
    }
    PRODUCT {
        string product_id PK "商品編號"
        string name "商品名稱"
        decimal price "單價"
    }

